import{G as e,W as t,rt as n,t as r}from"./chunks/framework.3zKPIMIf.js";import"./chunks/assets.CQcr3VdQ.js";var i=JSON.parse(`{"title":"cBlock","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}`),a={name:`index.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="cblock" tabindex="-1">cBlock <a class="header-anchor" href="#cblock" aria-label="Permalink to “cBlock”">​</a></h1><p>cBlock is a browser extension that hides Chinese content on any website.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to “Install”">​</a></h2><table tabindex="0"><thead><tr><th>Chrome</th><th>Firefox</th></tr></thead><tbody><tr><td><a href="https://chromewebstore.google.com/detail/oondbgdckgnijklignemhffjlkioodgp" target="_blank" rel="noreferrer"><img src="/images/chrome-web-store.png" alt="Available in the Chrome Web Store" width="198" height="60"></a></td><td><a href="https://addons.mozilla.org/firefox/addon/cblock/" target="_blank" rel="noreferrer"><img src="/images/firefox-add-ons.png" alt="Get the add-on for Firefox" width="172" height="60"></a></td></tr></tbody></table><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to “Permissions”">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Use</th></tr></thead><tbody><tr><td><code>storage</code></td><td>Stores cBlock’s settings and the results of website lookups</td></tr><tr><td><code>activeTab</code></td><td>Lets the popup find the current tab and its website</td></tr><tr><td><code>declarativeNetRequest</code></td><td>Blocks access to China-linked websites</td></tr><tr><td><code>http://*/*</code>, <code>https://*/*</code></td><td>Finds and hides Chinese content on all websites</td></tr></tbody></table><h2 id="how-cblock-works" tabindex="-1">How cBlock works <a class="header-anchor" href="#how-cblock-works" aria-label="Permalink to “How cBlock works”">​</a></h2><p>cBlock uses the four methods below to hide Chinese content and block connections to <a href="#what-to-hide">China-linked websites</a>. For details, see <a href="./how-it-works">How cBlock Decides</a>.</p><table tabindex="0"><thead><tr><th>Method</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Text filter</strong></td><td>Hides Chinese text and links to China-linked websites</td></tr><tr><td><strong>Name filter</strong></td><td>Hides items that mention a China-linked company or product (off by default)</td></tr><tr><td><strong>Website scripts</strong></td><td>Checks sellers, developers, and more that text alone can’t tell, website by website, and hides them</td></tr><tr><td><strong>Domain block</strong></td><td>Blocks China-linked websites before they load</td></tr></tbody></table><h2 id="popup" tabindex="-1">Popup <a class="header-anchor" href="#popup" aria-label="Permalink to “Popup”">​</a></h2><img src="/images/popup-en.png" alt="cBlock popup" width="320"><table tabindex="0"><thead><tr><th>Item</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Website name</strong></td><td>The website in the current tab</td></tr><tr><td><strong>On/off switch</strong></td><td>Turns cBlock on or off for this website. Shift-click turns it on or off for all websites</td></tr><tr><td><strong>Status</strong></td><td>Shows whether cBlock is on or off, or not available on this page</td></tr><tr><td><strong>Default for all websites</strong></td><td>The mode used on all websites</td></tr><tr><td><strong>Mode for this website</strong></td><td>The mode used only on this website. Click it again to go back to the default</td></tr><tr><td><strong>Options</strong></td><td>Opens the Options page</td></tr></tbody></table><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to “Options”">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Turn on cBlock</strong></td><td>Turns cBlock on or off for all websites</td></tr><tr><td><strong>Show the hidden count on the toolbar icon</strong></td><td>Shows on the toolbar icon how many items were hidden in the current tab</td></tr></tbody></table><h3 id="default-mode" tabindex="-1">Default mode <a class="header-anchor" href="#default-mode" aria-label="Permalink to “Default mode”">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>How blocked items look</th></tr></thead><tbody><tr><td><strong>Hide</strong></td><td>Items are not shown</td></tr><tr><td><strong>Blur</strong></td><td>Items are shown blurred (default)</td></tr><tr><td><strong>Mark</strong></td><td>Items are outlined with a dashed line and stay usable</td></tr><tr><td><strong>Empty</strong></td><td>Items are hidden, but their space stays blank so the layout doesn’t break</td></tr></tbody></table><h3 id="what-to-hide" tabindex="-1">What to hide <a class="header-anchor" href="#what-to-hide" aria-label="Permalink to “What to hide”">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Chinese text</strong></td><td>Hides posts, articles, and other items with Chinese text</td></tr><tr><td>└ <strong>Show Traditional Chinese</strong></td><td>Hides only Simplified Chinese</td></tr><tr><td><strong>Names of China-linked companies and products</strong></td><td>Hides items that mention a China-linked company or product (off by default)</td></tr><tr><td>└ Each genre</td><td>The genres to hide</td></tr><tr><td>└ <strong>Toggle All</strong></td><td>Turns all genres on or off</td></tr><tr><td><strong>Block pages of China-linked websites</strong></td><td>Blocks China-linked websites before they load</td></tr><tr><td><strong>Links to China-linked websites</strong></td><td>Hides links to China-linked websites</td></tr></tbody></table><blockquote><p>China-linked websites are websites of companies founded or based in China, and websites whose domain ends in <code>.cn</code>, <code>.中国</code>, or <code>.中國</code>.</p></blockquote><h3 id="website-lookups" tabindex="-1">Website lookups <a class="header-anchor" href="#website-lookups" aria-label="Permalink to “Website lookups”">​</a></h3><ul><li>All are off by default.</li><li>When turned on, cBlock asks the website you’re on about sellers, developers, authors, and more, to tell more accurately whether they’re based in China.</li><li>See the <a href="./privacy-policy#website-lookups">Privacy Policy</a> for details.</li><li>The X and pixiv lookups use private APIs, so the website may restrict your account. Use them at your own risk.</li></ul><table tabindex="0"><thead><tr><th>Website</th><th>What cBlock asks</th><th>What it hides</th></tr></thead><tbody><tr><td><strong>Amazon</strong></td><td>Seller’s address, phone, and name</td><td>Products by sellers based in China</td></tr><tr><td><strong>Steam</strong></td><td>Game’s developer and publisher</td><td>Games by studios based in China</td></tr><tr><td><strong>X</strong></td><td>Author’s account location and connection source</td><td>Posts by accounts based in China</td></tr><tr><td><strong>pixiv</strong></td><td>Artist’s profile</td><td>Works by artists based in China</td></tr></tbody></table><h3 id="mode-per-website" tabindex="-1">Mode per website <a class="header-anchor" href="#mode-per-website" aria-label="Permalink to “Mode per website”">​</a></h3><ul><li>You can set a mode per website. Enter one website and mode per line.</li><li>Set the mode to one of these four: <ul><li><code>hide</code></li><li><code>blur</code></li><li><code>mark</code></li><li><code>empty</code></li></ul></li><li>Websites not in the list use the default mode.</li></ul><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>youtube.com hide</span></span>
<span class="line"><span>news.yahoo.co.jp blur</span></span>
<span class="line"><span>news.example.com mark</span></span></code></pre></div><blockquote><p>cBlock runs on a listed website even if it is turned off on the parent domain. The more specific domain wins, so in the example above, <code>news.example.com</code> runs with <code>mark</code> even if <code>example.com</code> is in <a href="#websites-to-turn-off">Websites to turn off</a> below.</p></blockquote><h3 id="websites-to-turn-off" tabindex="-1">Websites to turn off <a class="header-anchor" href="#websites-to-turn-off" aria-label="Permalink to “Websites to turn off”">​</a></h3><p>Enter one website per line where cBlock should not run. In the example below, <code>www.example.com</code> is turned off too.</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>example.com</span></span></code></pre></div>`,29)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};